-- Class2Life — initial schema (V1)
-- Exported from docs/schema.dbml (the source of truth). Do not edit this file
-- after it is merged to main; schema changes go in a new migration.
--
-- UUID default note: dbdiagram exports uuid_generate_v4(), which needs the
-- uuid-ossp extension. We use gen_random_uuid() instead, which is built into
-- PostgreSQL 13+, so no CREATE EXTENSION is required.
--
-- Length note: the DBML says just "varchar"; we use VARCHAR(255) so the columns
-- line up with Hibernate's default String length and ddl-auto=validate stays happy.

-- ==========================================
-- ENUMS (native Postgres types)
-- ==========================================

CREATE TYPE user_role AS ENUM ('ADMIN', 'INSTRUCTOR', 'LEARNER');
CREATE TYPE user_status AS ENUM ('ACTIVE', 'SUSPENDED');
CREATE TYPE course_status AS ENUM ('DRAFT', 'PUBLISHED', 'HIDDEN');
CREATE TYPE lesson_type AS ENUM ('VIDEO', 'TEXT', 'LIVE_PRACTICE');
CREATE TYPE completion_status AS ENUM ('IN_PROGRESS', 'COMPLETED');
CREATE TYPE assignment_type AS ENUM ('QUIZ', 'FILE_SUBMISSION');
CREATE TYPE report_status AS ENUM ('PENDING', 'RESOLVED', 'DISMISSED');
CREATE TYPE notification_type AS ENUM ('NEW_CONTENT', 'DEADLINE', 'SYSTEM');
CREATE TYPE session_status AS ENUM ('SCHEDULED', 'ONGOING', 'COMPLETED');

-- ==========================================
-- ACCOUNTS & ADMIN
-- ==========================================

CREATE TABLE app_users (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    full_name     VARCHAR(255) NOT NULL,
    email         VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    role          user_role    NOT NULL DEFAULT 'LEARNER',
    status        user_status  NOT NULL DEFAULT 'ACTIVE',
    created_at    TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at    TIMESTAMP
);

CREATE TABLE password_resets (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    UUID         NOT NULL REFERENCES app_users (id),
    token_hash VARCHAR(255) NOT NULL,
    expire_at  TIMESTAMP    NOT NULL,
    used_at    TIMESTAMP,
    created_at TIMESTAMP    NOT NULL DEFAULT now()
);

CREATE TABLE admin_audit_logs (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    actor_id    UUID         NOT NULL REFERENCES app_users (id),
    action      VARCHAR(255) NOT NULL,
    entity_type VARCHAR(255),
    entity_id   UUID,
    created_at  TIMESTAMP    NOT NULL DEFAULT now()
);

-- ==========================================
-- COURSES & CONTENT
-- ==========================================

CREATE TABLE courses (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    instructor_id UUID           NOT NULL REFERENCES app_users (id),
    title         VARCHAR(255)   NOT NULL,
    description   TEXT,
    category      VARCHAR(255),
    status        course_status  NOT NULL DEFAULT 'DRAFT',
    created_at    TIMESTAMP      NOT NULL DEFAULT now(),
    updated_at    TIMESTAMP

);

CREATE TABLE lessons (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    course_id       UUID         NOT NULL REFERENCES courses (id),
    sequence_number INTEGER      NOT NULL,
    title           VARCHAR(255) NOT NULL,
    type            lesson_type  NOT NULL,
    content_url     VARCHAR(255),
    created_at      TIMESTAMP    NOT NULL DEFAULT now(),
    updated_at      TIMESTAMP,
    CONSTRAINT uq_lessons_course_sequence UNIQUE (course_id, sequence_number)
);

-- ==========================================
-- ENROLMENT & PROGRESS
-- ==========================================

CREATE TABLE enrolments (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id                 UUID              NOT NULL REFERENCES app_users (id),
    course_id               UUID              NOT NULL REFERENCES courses (id),
    completion_status       completion_status NOT NULL DEFAULT 'IN_PROGRESS',
    last_position_lesson_id UUID              REFERENCES lessons (id),
    enrolled_at             TIMESTAMP         NOT NULL DEFAULT now(),
    CONSTRAINT uq_enrolments_user_course UNIQUE (user_id, course_id)
);

CREATE TABLE lesson_progress (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    enrolment_id UUID    NOT NULL REFERENCES enrolments (id),
    lesson_id    UUID    NOT NULL REFERENCES lessons (id),
    is_completed BOOLEAN NOT NULL DEFAULT false,
    completed_at TIMESTAMP,
    CONSTRAINT uq_lesson_progress_enrolment_lesson UNIQUE (enrolment_id, lesson_id)
);

-- ==========================================
-- ASSIGNMENTS & ASSESSMENT
-- ==========================================

CREATE TABLE assignments (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    lesson_id    UUID            NOT NULL REFERENCES lessons (id),
    title        VARCHAR(255)    NOT NULL,
    type         assignment_type NOT NULL,
    instructions TEXT,
    pass_score   INTEGER,
    deadline     TIMESTAMP,
    created_at   TIMESTAMP       NOT NULL DEFAULT now(),
    updated_at   TIMESTAMP
);

CREATE TABLE submissions (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    assignment_id UUID         NOT NULL REFERENCES assignments (id),
    user_id       UUID         NOT NULL REFERENCES app_users (id),
    graded_by     UUID         REFERENCES app_users (id),
    file_url      VARCHAR(255),
    score         NUMERIC,
    feedback      TEXT,
    submitted_at  TIMESTAMP    NOT NULL DEFAULT now(),
    graded_at     TIMESTAMP
);

CREATE TABLE quiz_questions (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    assignment_id UUID    NOT NULL REFERENCES assignments (id),
    content       TEXT    NOT NULL,
    points        INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE quiz_options (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    question_id UUID    NOT NULL REFERENCES quiz_questions (id),
    content     TEXT    NOT NULL,
    is_correct  BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE quiz_attempts (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    assignment_id UUID      NOT NULL REFERENCES assignments (id),
    user_id       UUID      NOT NULL REFERENCES app_users (id),
    total_score   NUMERIC,
    attempted_at  TIMESTAMP NOT NULL DEFAULT now()
);

-- ==========================================
-- INTERACTION & NOTIFICATIONS
-- ==========================================

CREATE TABLE lesson_qna (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    lesson_id  UUID      NOT NULL REFERENCES lessons (id),
    author_id  UUID      NOT NULL REFERENCES app_users (id),
    parent_id  UUID      REFERENCES lesson_qna (id),
    content    TEXT      NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT now()
);

CREATE TABLE reported_contents (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    reporter_id          UUID         NOT NULL REFERENCES app_users (id),
    reported_entity_type VARCHAR(255) NOT NULL,
    reported_entity_id   UUID         NOT NULL,
    resolved_by          UUID         REFERENCES app_users (id),
    reason               TEXT         NOT NULL,
    status               report_status NOT NULL DEFAULT 'PENDING',
    created_at           TIMESTAMP    NOT NULL DEFAULT now(),
    resolved_at          TIMESTAMP
);

CREATE TABLE notifications (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    UUID              NOT NULL REFERENCES app_users (id),
    type       notification_type NOT NULL,
    content    TEXT              NOT NULL,
    is_read    BOOLEAN           NOT NULL DEFAULT false,
    created_at TIMESTAMP         NOT NULL DEFAULT now()
);

-- ==========================================
-- LIVE PRACTICE (ADVANCED COMPONENT)
-- ==========================================

CREATE TABLE live_sessions (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    lesson_id      UUID           NOT NULL REFERENCES lessons (id),
    host_id        UUID           NOT NULL REFERENCES app_users (id),
    scheduled_time TIMESTAMP      NOT NULL,
    status         session_status NOT NULL DEFAULT 'SCHEDULED',
    created_at     TIMESTAMP      NOT NULL DEFAULT now()
);

CREATE TABLE breakout_rooms (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id           UUID         NOT NULL REFERENCES live_sessions (id),
    name                 VARCHAR(255) NOT NULL,
    final_whiteboard_url VARCHAR(255),
    created_at           TIMESTAMP    NOT NULL DEFAULT now()
);

CREATE TABLE room_participants (
    id        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    room_id   UUID      NOT NULL REFERENCES breakout_rooms (id),
    user_id   UUID      NOT NULL REFERENCES app_users (id),
    joined_at TIMESTAMP NOT NULL DEFAULT now(),
    left_at   TIMESTAMP,
    CONSTRAINT uq_room_participants_room_user UNIQUE (room_id, user_id)
);

CREATE TABLE room_messages (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    room_id      UUID      NOT NULL REFERENCES breakout_rooms (id),
    sender_id    UUID      NOT NULL REFERENCES app_users (id),
    content      TEXT      NOT NULL,
    is_broadcast BOOLEAN   NOT NULL DEFAULT false,
    sent_at      TIMESTAMP NOT NULL DEFAULT now()
);

CREATE TABLE whiteboard_notes (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    room_id    UUID             NOT NULL REFERENCES breakout_rooms (id),
    created_by UUID             NOT NULL REFERENCES app_users (id),
    content    TEXT,
    pos_x      DOUBLE PRECISION NOT NULL,
    pos_y      DOUBLE PRECISION NOT NULL,
    color      VARCHAR(255),
    updated_at TIMESTAMP        NOT NULL DEFAULT now()
);

CREATE TABLE session_feedbacks (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id    UUID      NOT NULL REFERENCES live_sessions (id),
    learner_id    UUID      NOT NULL REFERENCES app_users (id),
    instructor_id UUID      NOT NULL REFERENCES app_users (id),
    comment       TEXT,
    rating        INTEGER,
    created_at    TIMESTAMP NOT NULL DEFAULT now()
);
